p='data/bc06.js';s=open(p,encoding='utf-8').read();ch=json.loads(re.search(r'=(\{.*\});?\s*$',s,re.S).group(1));slides=ch['modules'][0]['slides']
data={
4:{'title':'古代面包制作与发酵（酶的应用历史）','notes':'本页用古埃及面包制作模型、宴饮壁画和实物面包说明：人类早在古代就利用微生物和酶进行面团发酵、酿酒和制作发酵食品。面包制作是最早的“生物催化/发酵”实践之一，为学习酶的作用提供了历史背景。','points':['古代已利用发酵制作面包和酒','发酵依赖微生物和酶','酶学来自生产实践'],'explain':'图片展示古埃及面包制作模型、宴饮壁画与实物面包，说明人类很早就在利用发酵和酶。','q':'为什么酶学章节要展示古代面包制作和发酵？','a':'因为面包发酵、酿酒等是最早利用微生物和酶的实践，说明酶学来源于生产生活，并为后续学习酶的催化作用提供历史背景。'},
8:{'title':'催化剂降低活化能：自由能曲线','notes':'本页是反应进程-自由能图。纵轴为自由能，横轴为反应进程。非催化反应（虚线）要越过很高的能垒；催化反应（绿色实线）走另一条路径，峰值明显降低。两条曲线起点都是底物、终点都是产物，产物自由能低于底物，说明总自由能变化 ΔG 相同，反应仍是有利的；催化剂只降低活化能、加快反应，不改变平衡。','points':['纵轴自由能，横轴反应进程','非催化峰值高，催化峰值低','酶降低活化能','不改变底物/产物能级和平衡'],'explain':'图中比较非催化与催化反应的能量曲线：催化路径峰值更低，但底物和产物能级不变。','q':'酶降低活化能后，反应的底物、产物能级和平衡常数会改变吗？','a':'不会。酶只提供活化能更低的途径，加快达到平衡；底物和产物自由能不变，ΔG 和平衡常数也不变。'},
9:{'title':'非催化/一般催化剂/酶促反应的活化能比较','notes':'本页用三条能量曲线比较非催化反应、一般催化剂催化和酶促反应。黑线峰值最高，是一般非催化反应；绿色峰值居中，是一般催化剂；红色峰值最低，是酶促反应。三者底物和产物能级相同，反应总能量改变相同。说明酶比一般催化剂更显著地降低活化能，因此催化效率更高。','points':['黑：非催化；绿：一般催化剂；红：酶促','酶降低活化能最多','三者总能量变化相同'],'explain':'三条曲线说明酶促反应峰值最低、一般催化剂次之、非催化最高，但总能量变化一样。','q':'三条活化能曲线中，哪条代表酶促反应？为什么？','a':'红色曲线。酶促反应的活化能峰值最低，说明酶比一般催化剂更显著地降低活化能，催化效率更高。'},
23:{'title':'辅基和辅酶在催化中的作用（维生素来源）','notes':'本页表格列出常见辅基/辅酶、所含维生素和转移的基团。NAD+、NADP+来自尼克酰胺（维生素B3），传递氢/电子；FMN、FAD来自维生素B2，传递氢/电子；TPP来自维生素B1，转移醛类；辅酶A来自泛酸，转移酰基；磷酸吡哆醛来自维生素B6，转移氨基；四氢叶酸转移一碳单位；生物素转移二氧化碳。由此把维生素—辅酶—反应类型连起来。','points':['NAD+/NADP+：B3，传氢/电子','FMN/FAD：B2，传氢/电子','TPP：B1，传醛类','CoA：泛酸，传酰基','四氢叶酸：一碳单位'],'explain':'表格把辅酶、维生素来源和转移基团一一对应，是B族维生素与辅酶关系的核心表。','q':'FAD和FMN来自哪种维生素？它们主要传递什么？','a':'来自维生素B2（核黄素），主要传递氢原子/电子，参与氧化还原反应。'},
31:{'title':'国际分类：六大酶类','notes':'国际酶学委员会按催化反应类型把酶分为六大类：氧化还原酶、转移酶、水解酶、裂合酶、异构酶、连接酶。氧化还原酶催化电子/氢转移；转移酶催化基团转移；水解酶催化加水分解；裂合酶催化双键形成或移去基团；异构酶催化同分异构体互变；连接酶催化C—C、C—O、C—N、C—S键形成，并与ATP分解偶联。','points':['六大类名称','按反应类型分类','连接酶与ATP偶联','裂合酶与水解酶区别'],'explain':'本页列出六大酶类及其中英文名称，是酶分类的总纲。','q':'六大酶类中，哪一类催化反应必须与ATP分解偶联？','a':'连接酶（合成酶，ligases）。它们催化C—C、C—O、C—N、C—S键形成，反应与ATP分解偶联。'},
32:{'title':'国际酶分类表（英文）','notes':'本页为International Classification of Enzymes表：1氧化还原酶、2转移酶、3水解酶、4裂合酶、5异构酶、6连接酶，并列出各类催化反应类型。氧化还原酶传递电子/氢；转移酶转移基团；水解酶水解；裂合酶加成到双键或移去基团形成双键；异构酶分子内重排；连接酶通过缩合形成C—C、C—S、C—O、C—N键并与ATP裂解偶联。','points':['六类英文名','每类反应类型','连接酶=ATP偶联','分类依据是反应类型'],'explain':'英文分类表与前一页中文六大类一一对应，可用于记忆英文名称和反应类型。','q':'Lyases和Ligases分别催化什么类型的反应？','a':'Lyases催化双键的加成或移去基团形成双键；Ligases通过缩合形成C—C、C—S、C—O、C—N键，并与ATP裂解偶联。'},
48:{'title':'酶-底物“三点附着”学说','notes':'本页示意酶与底物的三点附着模型。A中底物的三个基团与酶表面的三个结合位点同时互补匹配，能形成稳定结合；B中底物取向不对，只有一个或两个点能接触，不能正确匹配，因此不能被有效催化。三点附着说明酶对底物的立体专一性：不仅要有结合，还要有正确的空间取向。','points':['A：三点互补匹配','B：取向错误，不匹配','解释立体专一性','结合需要正确空间取向'],'explain':'图中A为三点互补匹配，B为底物取向错误；说明酶不仅识别基团，还识别三维取向。','q':'三点附着学说如何解释酶的立体专一性？','a':'酶与底物至少需要三个位点同时互补匹配，底物的空间取向必须正确；取向错误的异构体不能形成有效三点结合，因此不能被催化。'},
51:{'title':'酶促反应时间进程曲线','notes':'本页是产物生成量随时间变化的曲线。开始阶段产物近似线性增加，斜率代表初速度；随后曲线变平，因为底物浓度下降、酶饱和程度降低、产物积累使逆反应增强、体系pH变化以及酶逐渐变性失活。测酶活力应选初速度阶段，避免底物消耗和产物抑制的影响。','points':['纵轴产物生成量，横轴时间','初期线性=初速度','后期平台化','原因：底物减少、产物抑制、逆反应、pH变化、酶失活'],'explain':'曲线先直线上升后变平；直线段用于测初速度，平台段说明反应条件已改变。','q':'为什么酶促反应时间曲线后期会变平？','a':'底物被消耗、酶饱和程度下降，产物积累使逆反应增强，体系pH变化，酶也可能变性失活，因此产物生成速率下降。'},
76:{'title':'工业应用：木瓜蛋白酶生产','notes':'本页是木瓜蛋白酶生产企业网站截图。木瓜蛋白酶是从木瓜中提取的蛋白酶，可用于食品加工、嫩肉、啤酒澄清、医药和日化等。该企业介绍其木瓜种植基地和年产约20吨天然木瓜蛋白酶，说明酶制剂已经从实验室走向工业化生产。','points':['木瓜蛋白酶来自木瓜','蛋白酶用于食品/医药/日化','酶制剂可工业化生产','生物工程产业应用'],'explain':'网页截图展示木瓜蛋白酶生产企业和产品，说明酶学知识在工业中的实际应用。','q':'木瓜蛋白酶主要来自什么原料？它属于哪类酶？','a':'来自木瓜，属于蛋白酶（水解酶类），可催化蛋白质水解。'}
}
